import React, { useState, useEffect, useRef } from 'react';
import {
  StyleSheet,
  Text,
  View,
  TouchableOpacity,
  ScrollView,
  SafeAreaView,
  ActivityIndicator,
  Alert,
  Platform,
} from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { LinearGradient } from 'expo-linear-gradient';
import { useSpeechRecognition } from './src/hooks/useSpeechRecognition';
import { initializeOpenAI, translateTextStreaming } from './src/services/translationService';
import { OPENAI_API_KEY } from '@env';

export default function App() {
  const [translatedText, setTranslatedText] = useState('');
  const [isTranslating, setIsTranslating] = useState(false);
  const [translationHistory, setTranslationHistory] = useState([]);
  const [lastTranslatedText, setLastTranslatedText] = useState('');
  const [accumulatedTranslations, setAccumulatedTranslations] = useState('');
  const [lastProcessedIndex, setLastProcessedIndex] = useState(0);

  const englishScrollViewRef = useRef(null);
  const japaneseScrollViewRef = useRef(null);
  const debounceTimerRef = useRef(null);
  const maxWaitTimerRef = useRef(null);
  const lastRecognizedLengthRef = useRef(0);

  const {
    isListening,
    recognizedText,
    partialText,
    error,
    startListening,
    stopListening,
  } = useSpeechRecognition();

  // 文の終わりを検出
