import React, { useState, useEffect, useRef } from 'react';
import {
  StyleSheet,
  Text,
  View,
  TouchableOpacity,
  ScrollView,
  SafeAreaView,
  ActivityIndicator,
  Alert,
  Platform,
} from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { LinearGradient } from 'expo-linear-gradient';
import { useSpeechRecognition } from './src/hooks/useSpeechRecognition';
import { initializeOpenAI, translateTextStreaming } from './src/services/translationService';
import { OPENAI_API_KEY } from '@env';

export default function App() {
  const [translatedText, setTranslatedText] = useState('');
  const [isTranslating, setIsTranslating] = useState(false);
  const [translationHistory, setTranslationHistory] = useState([]);
  const [lastTranslatedText, setLastTranslatedText] = useState('');
  const [accumulatedTranslations, setAccumulatedTranslations] = useState('');
  const [lastProcessedIndex, setLastProcessedIndex] = useState(0);

  const englishScrollViewRef = useRef(null);
  const japaneseScrollViewRef = useRef(null);
  const debounceTimerRef = useRef(null);
  const maxWaitTimerRef = useRef(null);
  const lastRecognizedLengthRef = useRef(0);
  const translationQueueRef = useRef([]);
  const isProcessingQueueRef = useRef(false);

  const {
    isListening,
    recognizedText,
    partialText,
    error,
    startListening,
    stopListening,
  } = useSpeechRecognition();

  // 文の終わりを検出
  const findCompletedSentences = (text) => {
    // 文の終わりのパターン: . ! ?
    const sentenceEndPattern = /[.!?]\s+/g;
    let lastMatch = null;
    let match;

    while ((match = sentenceEndPattern.exec(text)) !== null) {
      lastMatch = match;
    }

    if (lastMatch) {
      const endIndex = lastMatch.index + lastMatch[0].length;
      return {
        completedPart: text.substring(0, endIndex).trim(),
        remainingPart: text.substring(endIndex).trim(),
        endIndex: endIndex
      };
    }

    return null;
  };

  // OpenAI初期化とネットワークテスト
  useEffect(() => {
    console.log('API Key check:', OPENAI_API_KEY ? 'Found' : 'Not found');

    // ネットワーク接続テスト
    const testNetwork = async () => {
      try {
        console.log('Testing network connection...');
        const xhr = new XMLHttpRequest();
        xhr.open('GET', 'https://www.google.com');
        xhr.onload = () => {
          console.log('Network test success - Google reachable');
        };
        xhr.onerror = (e) => {
          console.log('Network test failed - Cannot reach Google', e);
        };
        xhr.send();
      } catch (error) {
        console.log('Network test error:', error);
      }
    };

    testNetwork();

    if (OPENAI_API_KEY) {
      initializeOpenAI(OPENAI_API_KEY);
      console.log('OpenAI initialized');
    } else {
      Alert.alert('エラー', '.envファイルにOPENAI_API_KEYを設定してください');
    }
  }, []);

  // チャンク単位でリアルタイム翻訳
  useEffect(() => {
    if (!recognizedText || recognizedText.trim().length === 0 || !isListening) {
      // クリーンアップ
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
      if (maxWaitTimerRef.current) clearTimeout(maxWaitTimerRef.current);
      return;
    }

    // 新しく追加された部分
    const newPart = recognizedText.substring(lastProcessedIndex);
    const wordCount = newPart.trim().split(/\s+/).length;

    // 最初のテキストが来たら最大待機タイマーを開始
    if (lastRecognizedLengthRef.current === 0 && recognizedText.length > 0) {
      maxWaitTimerRef.current = setTimeout(() => {
        const pendingText = recognizedText.substring(lastProcessedIndex).trim();
        if (pendingText && !isTranslating) {
          console.log('Max wait time reached. Force translating:', pendingText);
          handleTranslateSentence(pendingText);
          setLastProcessedIndex(recognizedText.length);
        }
      }, 5000); // 最大5秒待機
    }

    lastRecognizedLengthRef.current = recognizedText.length;

    // デバウンスタイマーをクリア
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    // 新しいデバウンスタイマーを設定
    debounceTimerRef.current = setTimeout(() => {
      if (wordCount >= 15 && !isTranslating) {
        // 15単語以上溜まった
        console.log('Word threshold reached. Translating chunk:', newPart);
        handleTranslateSentence(newPart);
        setLastProcessedIndex(recognizedText.length);
        // 最大待機タイマーをリセット
        if (maxWaitTimerRef.current) clearTimeout(maxWaitTimerRef.current);
        lastRecognizedLengthRef.current = 0;
      } else if (wordCount >= 5 && !isTranslating) {
        // 5単語以上あり、1.2秒間更新がない
        console.log('Pause detected. Translating chunk:', newPart);
        handleTranslateSentence(newPart);
        setLastProcessedIndex(recognizedText.length);
        // 最大待機タイマーをリセット
        if (maxWaitTimerRef.current) clearTimeout(maxWaitTimerRef.current);
        lastRecognizedLengthRef.current = 0;
      }
    }, 1200); // 1.2秒待つ

    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [recognizedText, isListening]);

  // 音声認識が停止したら残りの部分を翻訳
  useEffect(() => {
    if (!isListening && recognizedText && recognizedText.length > lastProcessedIndex) {
      const remainingText = recognizedText.substring(lastProcessedIndex).trim();
      if (remainingText && !isTranslating) {
        console.log('Speech stopped. Translating remaining:', remainingText);
        handleTranslateSentence(remainingText);
        setLastProcessedIndex(recognizedText.length);
      }
    }
  }, [isListening]);

  const processTranslationQueue = async () => {
    if (isProcessingQueueRef.current || translationQueueRef.current.length === 0) {
      return;
    }

    isProcessingQueueRef.current = true;
    setIsTranslating(true);

    while (translationQueueRef.current.length > 0) {
      const sentenceText = translationQueueRef.current.shift();

      try {
        console.log('Translating from queue:', sentenceText);
        const translation = await translateTextStreaming(sentenceText, () => {});

        // 翻訳を蓄積して表示（既存の翻訳に追加）
        setTranslatedText(prev => {
          const newText = prev + (prev ? ' ' : '') + translation;
          // 翻訳が更新されたら自動スクロール
          setTimeout(() => {
            japaneseScrollViewRef.current?.scrollToEnd({ animated: true });
          }, 100);
          return newText;
        });

        console.log('Translated and appended:', translation);
      } catch (err) {
        console.error('Translation error:', err);
      }
    }

    isProcessingQueueRef.current = false;
    setIsTranslating(false);
  };

  const handleTranslateSentence = async (sentenceText) => {
    if (!sentenceText) {
      return;
    }

    // キューに追加
    translationQueueRef.current.push(sentenceText);
    console.log('Added to queue. Queue length:', translationQueueRef.current.length);

    // キュー処理を開始
    processTranslationQueue();
  };

  // 英語の文字起こしが更新されたら自動スクロール
  useEffect(() => {
    if (recognizedText) {
      setTimeout(() => {
        englishScrollViewRef.current?.scrollToEnd({ animated: true });
      }, 100);
    }
  }, [recognizedText]);

  const handleMicPress = () => {
    if (isListening) {
      stopListening();
    } else {
      // 新しい録音開始時にリセット
      setTranslatedText('');
      setLastProcessedIndex(0);
      lastRecognizedLengthRef.current = 0;
      translationQueueRef.current = [];
      isProcessingQueueRef.current = false;
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
      if (maxWaitTimerRef.current) clearTimeout(maxWaitTimerRef.current);
      startListening();
    }
  };

  const displayText = recognizedText || 'Tap to speak...';

  return (
    <View style={styles.container}>
      <StatusBar style="light" />

      <LinearGradient
        colors={['#1a1a2e', '#16213e', '#0f3460']}
        style={styles.gradient}
      >
        {/* ヘッダー */}
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Realtime Translation</Text>
          <View style={styles.languageBadge}>
            <Text style={styles.badgeText}>EN → JA</Text>
          </View>
        </View>

        {/* メインコンテンツ */}
        <View style={styles.mainContent}>
          {/* 英語表示エリア */}
          <View style={styles.glassCard}>
            <View style={styles.cardHeader}>
              <Text style={styles.cardTitle}>English</Text>
              {isListening && <View style={styles.recordingIndicator} />}
            </View>
            <ScrollView
              ref={englishScrollViewRef}
              style={styles.textScrollView}
            >
              <Text style={[styles.text, partialText && styles.partialText]}>
                {isListening ? displayText : recognizedText || 'Waiting for input...'}
              </Text>
            </ScrollView>
          </View>

          {/* 翻訳表示エリア */}
          <View style={styles.glassCard}>
            <View style={styles.cardHeader}>
              <Text style={styles.cardTitle}>日本語</Text>
              {isTranslating && <ActivityIndicator size="small" color="#60a5fa" />}
            </View>
            <ScrollView
              ref={japaneseScrollViewRef}
              style={styles.textScrollView}
            >
              <Text style={styles.text}>{translatedText || '翻訳待機中...'}</Text>
            </ScrollView>
          </View>
        </View>

        {/* コントロールボタン */}
        <View style={styles.controls}>
          <TouchableOpacity
            style={[styles.micButton, isListening && styles.micButtonActive]}
            onPress={handleMicPress}
            activeOpacity={0.8}
          >
            <View style={styles.micButtonInner}>
              <Text style={styles.micIcon}>{isListening ? '⏸' : '●'}</Text>
              <Text style={styles.micButtonText}>{isListening ? 'Stop' : 'Speak'}</Text>
            </View>
          </TouchableOpacity>

          {error && (
            <View style={styles.errorContainer}>
              <Text style={styles.errorText}>{error}</Text>
            </View>
          )}
        </View>
      </LinearGradient>
    </View>
  );
}

